import React, { FunctionComponent } from 'react';
import classNames from 'classnames';
import { Field } from 'react-final-form';
import { defineMessages } from 'react-intl';
import { useTranslation } from '@getvim/translate';
import InputValidationMessage from '../../inputValidationMessage';
import LabeledInput from '../../labeledInput';
import es from './es.json';

const messages = defineMessages({
  required: {
    defaultMessage: '{label} is required',
    id: 'required',
  },
  tooShort: {
    defaultMessage: '{label} must be at least {MIN_NAME_LENGH} characters',
    id: 'tooshort',
  },
  tooLong: {
    defaultMessage: '{label} must not exceed {MAX_NAME_LENGH} characters',
    id: 'toolong',
  },
  specialcharacters: {
    defaultMessage: 'Special characters are not allowed',
    id: 'specialcharacters',
  },
  numbers: {
    defaultMessage: 'Numbers are not allowed',
    id: 'numbers',
  },
});

const MIN_NAME_LENGH = 2;
const MAX_NAME_LENGH = 50;

const isNameInputValid = (nameInput, label, intl) => {
  if (!nameInput) return intl.formatMessage(messages.required, { label });

  const nameWithoutWhitespaces = nameInput.replace(/\s+/g, '');
  if (nameWithoutWhitespaces.length === 0) return intl.formatMessage(messages.required, { label });

  const regNumbers = /\d/;
  const containsNumbers = regNumbers.test(nameWithoutWhitespaces);
  if (containsNumbers) return intl.formatMessage(messages.numbers);

  const regName = /^[ a-zñáéíóúüA-ZÑÁÉÍÓÚ\-.'()]+$/;
  const containsValidCharacters = regName.test(nameWithoutWhitespaces);
  if (!containsValidCharacters) return intl.formatMessage(messages.specialcharacters);

  if (nameWithoutWhitespaces.length < MIN_NAME_LENGH)
    return intl.formatMessage(messages.tooShort, { label, MIN_NAME_LENGH });

  if (nameWithoutWhitespaces.length > MAX_NAME_LENGH)
    return intl.formatMessage(messages.tooLong, { label, MAX_NAME_LENGH });

  return undefined;
};

export type NameInputProps = {
  id?: string;
  label: string;
  name: string;
  className?: string;
  placeholder?: string;
};

const FormNameInput: FunctionComponent<NameInputProps> = ({
  id,
  label,
  name,
  placeholder,
  className,
}) => {
  const intl = useTranslation({ es } as any);
  return (
    <Field
      name={name}
      validate={(nameInput) => isNameInputValid(nameInput, label, intl)}
      render={({ input, meta }) => (
        <div className="name-input">
          <LabeledInput
            id={id}
            className={classNames(className, meta.error && meta.touched && 'has-error')}
            htmlFor={id}
            label={label}
            active={meta.active || !!input.value}
            type="text"
            placeholder={placeholder}
            {...input}
          />
          {meta.error && meta.touched && (
            <InputValidationMessage>{meta.error}</InputValidationMessage>
          )}
        </div>
      )}
    />
  );
};

export default FormNameInput;
